CREATE OR REPLACE FUNCTION public.claim_library_download(resource_uuid uuid, check_env text) RETURNS TABLE(content text, remaining integer, resets_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE uid uuid := auth.uid(); sub public.subscriptions%ROWTYPE; item public.knowledge_resources%ROWTYPE; used_count integer; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in to download.'; END IF; IF check_env NOT IN ('live','sandbox') THEN RAISE EXCEPTION 'Invalid billing environment.'; END IF; SELECT * INTO item FROM public.knowledge_resources WHERE id = resource_uuid AND kind = 'library' AND published AND access_level = 'analyst' FOR SHARE; IF NOT FOUND OR item.rights_status NOT IN ('OWNED_BY_VERFIAI','PUBLIC_DOMAIN','OPEN_LICENSED','PARTNER_LICENSED') OR NOT item.hosting_allowed OR NOT item.redistribution_allowed OR item.full_content IS NULL OR (item.rights_status IN ('OPEN_LICENSED','PARTNER_LICENSED') AND (NOT item.commercial_reuse_allowed OR item.permission_reference IS NULL OR item.rights_reviewed_at IS NULL)) THEN RAISE EXCEPTION 'This resource is not available for download.'; END IF; SELECT * INTO sub FROM public.subscriptions WHERE user_id = uid AND environment = check_env AND product_id = 'analyst_plan' AND status IN ('active','trialing') AND current_period_start <= now() AND current_period_end > now() ORDER BY created_at DESC LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'An active Analyst plan is required.'; END IF; PERFORM pg_advisory_xact_lock(hashtext(uid::text || ':' || sub.id::text)); SELECT count(*) INTO used_count FROM public.resource_downloads WHERE user_id = uid AND subscription_id = sub.id AND period_start = sub.current_period_start; IF NOT EXISTS (SELECT 1 FROM public.resource_downloads WHERE user_id = uid AND resource_id = resource_uuid AND file_version = item.file_version AND subscription_id = sub.id AND period_start = sub.current_period_start) THEN IF used_count >= 50 THEN RAISE EXCEPTION 'Your 50 Evidence Library downloads are used for this billing cycle.'; END IF; INSERT INTO public.resource_downloads(resource_id,user_id,subscription_id,period_start,period_end,file_version) VALUES (resource_uuid,uid,sub.id,sub.current_period_start,sub.current_period_end,item.file_version); used_count := used_count + 1; END IF; RETURN QUERY SELECT item.full_content, 50 - used_count, sub.current_period_end; END $$;
REVOKE ALL ON FUNCTION public.claim_library_download(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.claim_library_download(uuid,text) TO authenticated;